package main

import (
	"fmt"
	"strings"
)

// ==========================================
// FV-Julia 성능 분석기
// ==========================================

type PerformanceIssue struct {
	severity string // "CRITICAL", "HIGH", "MEDIUM", "LOW"
	location string
	problem  string
	impact   string
	fix      string
}

var issues []PerformanceIssue

// ==========================================
// 1. O(n²) 알고리즘 탐지
// ==========================================

func analyzeNestedLoops() {
	fmt.Println("[ANALYSIS] Nested Loops (O(n²) detection)")
	fmt.Println("─────────────────────────────────────────")

	// string_split 함수: O(n*m) 복잡도
	issues = append(issues, PerformanceIssue{
		severity: "MEDIUM",
		location: "stdlib/string.fl:225-242",
		problem:  "string_split() uses nested while loops (separator search in each iteration)",
		impact:   "O(n*m) where n=string length, m=separator length. For 1000-char string: ~1M operations",
		fix:      "Use built-in split or implement Boyer-Moore algorithm for O(n+m)",
	})

	// dict_remove 함수: O(n²) 배열 복사
	issues = append(issues, PerformanceIssue{
		severity: "HIGH",
		location: "stdlib/collections.fl:336-346",
		problem:  "dict_remove() rebuilds entire array for each removal (array concatenation)",
		impact:   "O(n²) when removing multiple items. Removing 100 items from 1000-item dict: ~500K operations",
		fix:      "Use index-based removal or linked list, or mark-and-sweep approach",
	})

	// array_contains: O(n) linear search
	issues = append(issues, PerformanceIssue{
		severity: "LOW",
		location: "stdlib/collections.fl:64-73",
		problem:  "array_contains() linear search through entire array",
		impact:   "O(n) per search. No indexing. Fine for small arrays (<1000), bad for large.",
		fix:      "Use hash set for O(1) lookup if used frequently",
	})

	// string_index_of: O(n*m) naive search
	issues = append(issues, PerformanceIssue{
		severity: "MEDIUM",
		location: "compiler/main.fv:759-775",
		problem:  "string_index_of() naive substring search (character-by-character comparison)",
		impact:   "O(n*m) where n=haystack length, m=needle length. String 10K chars, pattern 100 chars: ~1M ops",
		fix:      "Implement KMP or use built-in indexOf",
	})

	for i, issue := range issues {
		if strings.Contains(issue.location, "O(n²)") || strings.Contains(issue.problem, "nested") {
			fmt.Printf("%d. [%s] %s\n", i+1, issue.severity, issue.problem)
			fmt.Printf("   Location: %s\n", issue.location)
			fmt.Printf("   Impact: %s\n", issue.impact)
			fmt.Println()
		}
	}
}

// ==========================================
// 2. 메모리 사용 패턴 분석
// ==========================================

func analyzeMemoryPatterns() {
	fmt.Println("[ANALYSIS] Memory Usage Patterns")
	fmt.Println("─────────────────────────────────────────")

	// 임시 배열 생성
	issues = append(issues, PerformanceIssue{
		severity: "MEDIUM",
		location: "stdlib/string.fl:57-71 (to_uppercase)",
		problem:  "string_uppercase() creates new string char-by-char (immutable string concatenation)",
		impact:   "For 10K string: creates 10K intermediate strings. Memory spike: O(n²)",
		fix:      "Use string builder or character array, then join once",
	})

	// 파라미터 복사
	issues = append(issues, PerformanceIssue{
		severity: "LOW",
		location: "stdlib/collections.fl (all functions)",
		problem:  "All array/dict functions receive copies of data (pass-by-value semantics)",
		impact:   "For 1M-element array: copies entire array on each call",
		fix:      "Use pass-by-reference if language supports, or return new structures",
	})

	for i, issue := range issues {
		if strings.Contains(issue.problem, "Memory") || strings.Contains(issue.problem, "creates") {
			fmt.Printf("%d. [%s] %s\n", i+1, issue.severity, issue.problem)
			fmt.Printf("   Location: %s\n", issue.location)
			fmt.Printf("   Impact: %s\n", issue.impact)
			fmt.Println()
		}
	}
}

// ==========================================
// 3. 숨겨진 버그 (엣지 케이스)
// ==========================================

func analyzePotentialBugs() {
	fmt.Println("[ANALYSIS] Potential Hidden Bugs (Edge Cases)")
	fmt.Println("─────────────────────────────────────────")

	bugs := []PerformanceIssue{
		{
			severity: "CRITICAL",
			location: "stdlib/string.fl:196-220 (string_trim)",
			problem:  "string_trim() may fail with only whitespace strings",
			impact:   "string_trim('   ') should return '', but logic may return substring bounds error",
			fix:      "Test: string_trim('   ') → verify empty string returned",
		},
		{
			severity: "HIGH",
			location: "stdlib/math.fl:60-66 (newton_sqrt)",
			problem:  "newton_sqrt() doesn't handle x=0.0 correctly (0/0 division in Newton's method)",
			impact:   "newton_sqrt(0.0) with initial guess=0.0 causes division by zero",
			fix:      "Add special case: if x == 0.0 return 0.0 before Newton loop",
		},
		{
			severity: "MEDIUM",
			location: "stdlib/math.fl:262-270 (random)",
			problem:  "random() uses global mutable state (random_seed) - not thread-safe",
			impact:   "Concurrent calls to random() will race condition. Same seed every run.",
			fix:      "Use proper PRNG with independent seeds or thread-local state",
		},
		{
			severity: "HIGH",
			location: "stdlib/collections.fl:93-125 (quicksort)",
			problem:  "quicksort() modifies array in-place without handling duplicates well",
			impact:   "Partition function may not handle duplicate pivots (O(n²) degenerate case)",
			fix:      "Implement 3-way partition for better duplicate handling",
		},
		{
			severity: "MEDIUM",
			location: "stdlib/string.fl:225-242 (string_split)",
			problem:  "string_split() with empty separator - infinite loop?",
			impact:   "string_split('hello', '') may cause infinite loop",
			fix:      "Test and add guard: if sep.length() == 0 return [s]",
		},
		{
			severity: "LOW",
			location: "stdlib/io.fl:46-105 (try_parse_int)",
			problem:  "try_parse_int() doesn't handle overflow - may wrap around for huge numbers",
			impact:   "try_parse_int('99999999999999999') silently overflows instead of Err",
			fix:      "Add overflow check: if result > MAX_INT return Err",
		},
		{
			severity: "MEDIUM",
			location: "compiler/main.fv:737-742 (extract_element_type)",
			problem:  "extract_element_type() fails with nested types like Array[Array[Int]]",
			impact:   "Array[Array[Int]] finds first '[' and ']', missing inner type",
			fix:      "Implement bracket counting for proper nesting",
		},
		{
			severity: "HIGH",
			location: "stdlib/collections.fl:222-227 (array_slice)",
			problem:  "array_slice() uses substring() which may not work as expected for arrays",
			impact:   "Mixing string operations on arrays - type mismatch",
			fix:      "Implement proper array slicing (copy elements, not substring)",
		},
	}

	for i, bug := range bugs {
		fmt.Printf("%d. [%s] %s\n", i+1, bug.severity, bug.problem)
		fmt.Printf("   Location: %s\n", bug.location)
		fmt.Printf("   Impact: %s\n", bug.impact)
		fmt.Printf("   Fix: %s\n", bug.fix)
		fmt.Println()
	}
}

// ==========================================
// 4. 컴파일러 병목 분석
// ==========================================

func analyzeCompilerBottlenecks() {
	fmt.Println("[ANALYSIS] Compiler Bottlenecks")
	fmt.Println("─────────────────────────────────────────")

	bottlenecks := []struct {
		stage    string
		problem  string
		impact   string
		solution string
	}{
		{
			stage:    "Lexer",
			problem:  "Tokenize re-scans same string multiple times (whitespace, comments, operators)",
			impact:   "For 100K-line file: ~300K character re-scans",
			solution: "Single-pass tokenizer with lookahead buffer",
		},
		{
			stage:    "Parser",
			problem:  "parse_function_def() copies token arrays in loops",
			impact:   "For 1000-line file with 100 functions: ~500K array copies",
			solution: "Use index ranges instead of copying arrays",
		},
		{
			stage:    "TypeChecker",
			problem:  "Type checking doesn't memoize results - recalculates same types",
			impact:   "For complex nested types: exponential recalculation",
			solution: "Implement type cache/memo table",
		},
		{
			stage:    "CodeGen",
			problem:  "String concatenation in loops (code += ...)",
			impact:   "For 10K AST nodes: creates 10K intermediate strings",
			solution: "Use string builder pattern, collect all parts, join once",
		},
	}

	for i, bn := range bottlenecks {
		fmt.Printf("%d. [%s] %s\n", i+1, bn.stage, bn.problem)
		fmt.Printf("   Impact: %s\n", bn.impact)
		fmt.Printf("   Solution: %s\n", bn.solution)
		fmt.Println()
	}
}

// ==========================================
// 5. 성능 최적화 우선순위
// ==========================================

func printOptimizationPriority() {
	fmt.Println("\n[PRIORITY] Optimization Roadmap")
	fmt.Println("─────────────────────────────────────────")

	priority := []struct {
		rank   int
		fix    string
		effort string
		gain   string
	}{
		{1, "Implement string builder for string operations", "2h", "50% faster string handling"},
		{2, "Fix newton_sqrt() division by zero", "30m", "Prevents crashes"},
		{3, "Optimize array_slice() (type mismatch)", "1h", "Correctness"},
		{4, "Add overflow check to try_parse_int()", "1h", "Safety"},
		{5, "Implement bracket counting for nested types", "1.5h", "Handles Array[Array[T]]"},
		{6, "Memoize type checking results", "2h", "30% faster compilation"},
		{7, "Replace string_split() with efficient algorithm", "1.5h", "O(n+m) instead of O(n*m)"},
		{8, "Implement 3-way quicksort partition", "1.5h", "Handles duplicates"},
		{9, "Add thread-local PRNG state", "1h", "Thread safety"},
		{10, "Single-pass lexer with lookahead", "3h", "20% faster tokenization"},
	}

	for _, p := range priority {
		fmt.Printf("%d. %s\n", p.rank, p.fix)
		fmt.Printf("   Effort: %s | Gain: %s\n", p.effort, p.gain)
	}
}

// ==========================================
// 6. 복잡도 비교
// ==========================================

func printComplexityComparison() {
	fmt.Println("\n[COMPLEXITY] Current vs Optimal")
	fmt.Println("─────────────────────────────────────────")

	comparisons := []struct {
		function string
		current  string
		optimal  string
		data     string
	}{
		{"string_split", "O(n*m)", "O(n+m)", "1000-char string: 1M ops → 2K ops"},
		{"dict_remove", "O(n²)", "O(n)", "Remove from 1K dict: 500K ops → 1K ops"},
		{"string_uppercase", "O(n²) memory", "O(n) memory", "10K string: 50MB → 10KB"},
		{"array_contains", "O(n)", "O(1) with hash", "Search 1M items: 1M ops → 1 op"},
		{"quicksort", "O(n²) worst", "O(n log n) avg", "1K items: 1M ops → 10K ops"},
		{"string_index_of", "O(n*m)", "O(n+m) with KMP", "Find pattern: linear scan → one pass"},
	}

	for _, c := range comparisons {
		fmt.Printf("%s:\n", c.function)
		fmt.Printf("  Current:  %s\n", c.current)
		fmt.Printf("  Optimal:  %s\n", c.optimal)
		fmt.Printf("  Real data: %s\n", c.data)
		fmt.Println()
	}
}

func main() {
	fmt.Println("========================================")
	fmt.Println("FV-Julia Performance & Bug Analysis")
	fmt.Println("Phase E: 최적화 & 버그 사냥")
	fmt.Println("========================================\n")

	analyzeNestedLoops()
	fmt.Println()

	analyzeMemoryPatterns()
	fmt.Println()

	analyzePotentialBugs()

	analyzeCompilerBottlenecks()

	printComplexityComparison()

	printOptimizationPriority()

	fmt.Println("\n========================================")
	fmt.Printf("Total Issues Found: %d\n", len(issues))
	fmt.Println("CRITICAL: Fix immediately")
	fmt.Println("HIGH: Fix before production")
	fmt.Println("MEDIUM: Fix for performance")
	fmt.Println("LOW: Nice to have")
	fmt.Println("========================================")
}

